		assertThat(answers).extracting(Answer::status)
				.containsExactlyInAnyOrder(CREATED.value(), CONFLICT.value());
		refusalIn(answers).body().jsonPath("$.type")
				.isEqualTo(ProblemType.REQUEST_IN_PROGRESS.urn());

